class Order {
  items: {price:number, quantity:number}[] = [];
}

class Invoice {
  constructor(private order: Order) {}
  calculate(): number {
    return this.order.items.reduce((s, i) => s + i.price * i.quantity, 0);
  }
}

class Invoice {
  constructor(private order: Order) {}
  calculateTotal(): number {
    return this.order.items.reduce((s, i) => s + i.price * i.quantity, 0)
      - this.order.customer.getDiscount();
  }
}

