class Invoice {
  constructor(private order: Order) {}
  total(): number {
    return this.order.items.reduce((s, i) => s + i.price * i.quantity, 0) - this.order.customer.getDiscount();
  }
}

// Version B: calculation in Order
class Order {
  items: { price: number; quantity: number }[] = [];
  customer: Customer;
  total(): number {
    return this.items.reduce((s, i) => s + i.price * i.quantity, 0) - this.customer.getDiscount();
  }
}
